import glob

DEADLINE = "2026-10-15"

counts = {}
for path in glob.glob("signup/*.csv"):
    with open(path, encoding="utf-8") as f:
        next(f)
        for line in f:
            course, day = line.strip().split(",")
            if day < DEADLINE:
                counts[course] = counts.get(course, 0) + 1
for course in sorted(counts):
    print(f"{course} {counts[course]}")
